using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Swashbuckle.AspNetCore.Annotations;using GraphApi.Models.FNZ.Cuentas;using GraphApi.Services.FNZ.Cuentas;namespace GraphApi.Controllers.FNZ.Cuentas{    /// <summary>    /// Gestión de Cuentas: consulta, creación, actualización y borrado.    /// </summary>    [ApiController]    [Authorize]    [Route("FNZ/[controller]")]    [Produces("application/json")]    [SwaggerTag("Operaciones sobre Cuentas")]    public class CuentasController : Controller    {        private readonly ICuentasService _objService;        public CuentasController(ICuentasService objService)        {            _objService = objService;        }        /// <summary>        /// Obtiene todos los Cuentas, con filtros opcionales.        /// </summary>        /// <param name="userId">Id de usuario (header "UserID").</param>        /// <param name="windowName">Nombre de la aplicación (header "WindowName").</param>        /// <param name="cuentaID">CuentaID</param>        /// <param name="cuenta">Cuenta</param>        /// <param name="tipo">Tipo</param>        /// <param name="saldo">Saldo</param>        /// <param name="responsableUsuarioID">ResponsableUsuarioID</param>        /// <param name="bEliminado">bEliminado</param>        /// <returns>Listado de Cuentas</returns>        [HttpGet]        [SwaggerOperation(            Summary = "Listar Cuentas",            Description = "Devuelve Cuentas aplicando filtros opcionales."        )]        [ProducesResponseType(typeof(IEnumerable<clReadCuentas>), StatusCodes.Status200OK)]        public async Task<ActionResult<IEnumerable<clReadCuentas>>> GetAll(            [FromHeader(Name = "UserID")] int nUserId,            [FromHeader(Name = "WindowName")] string sWindowName,            [FromQuery] int? cuentaID,            [FromQuery] string? cuenta,            [FromQuery] string? tipo,            [FromQuery] decimal? saldo,            [FromQuery] int? responsableUsuarioID,            [FromQuery] bool? bEliminado,            [FromQuery] string? columnNames)        {            var vList = await _objService.GetCuentasDynamic(                cuentaID,                 cuenta,                 tipo,                 saldo,                 responsableUsuarioID,                 bEliminado,                 columnNames, nUserId, sWindowName);              return vList.Count()==0  ? NotFound() :  Ok(vList);        }        /// <summary>        /// Crea un nuevo Cuenta.        /// </summary>        /// <param name="userId">Id de usuario (header "UserID").</param>        /// <param name="windowName">Nombre de la aplicación (header "WindowName").</param>        /// <param name="input">Datos del Cuenta a crear.</param>        /// <returns>El Cuenta recién creado.</returns>        [HttpPost]        [SwaggerOperation(            Summary = "Crear Cuentas",            Description = "Inserta un nuevo Cuenta en la base de datos."        )]        [ProducesResponseType(typeof(clReadCuentas), StatusCodes.Status201Created)]        public async Task<ActionResult<clReadCuentas>> Create(            [FromHeader(Name = "UserID")] int nUserId,            [FromHeader(Name = "WindowName")] string sWindowName,            [FromBody] clCreateCuentas objInput)        {            var vCreated = await _objService.CreateCuentas(objInput, nUserId, sWindowName);            return vCreated is null ? NoContent() : vCreated;        }        /// <summary>        /// Actualización parcial de Cuenta.        /// </summary>        /// <param name="userId">Id de usuario (header "UserID").</param>        /// <param name="windowName">Nombre de la aplicación (header "WindowName").</param>        /// <param name="input">Campos a actualizar y el ID del Cuenta.</param>        /// <returns>El Cuenta actualizado.</returns>        [HttpPatch]        [SwaggerOperation(            Summary = "Actualizar Cuentas",            Description = "Actualiza uno o varios campos de Cuenta existente."        )]        [ProducesResponseType(typeof(clReadCuentas), StatusCodes.Status200OK)]        public async Task<ActionResult<clReadCuentas>> Patch(            [FromHeader(Name = "UserID")] int nUserId,            [FromHeader(Name = "WindowName")] string sWindowName,            [FromBody] clUpdateCuentas objInput)        {            var vUpdated = await _objService.UpdateCuentas(objInput, nUserId, sWindowName);            return vUpdated is null ? NotFound() : Ok(vUpdated);        }        /// <summary>        /// Elimina un Cuenta por su ID.        /// </summary>        [HttpDelete("{nCuentasID:int}")]        [SwaggerOperation(            Summary = "Eliminar Cuenta",            Description = "Borra un Cuenta si existe."        )]        [ProducesResponseType(StatusCodes.Status204NoContent)]        public async Task<IActionResult> Delete(int nCuentasID)        {            var success = await _objService.DeleteCuentas(nCuentasID);            return success ? NoContent() : NotFound();        }    }}